def cmp_semver(a: str, b: str) -> int:
    def parse_version(v: str):
        # Split off build metadata
        if '+' in v:
            v = v.split('+', 1)[0]
        # Split off pre-release
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        # Parse core version
        parts = core.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version: {v}")
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])
        return (major, minor, patch, pre)

    def compare_pre_release(pre_a, pre_b):
        # None means no pre-release, which has higher precedence than any pre-release
        if pre_a is None and pre_b is None:
            return 0
        if pre_a is None:
            return 1  # a has no pre-release, so a > b
        if pre_b is None:
            return -1  # b has no pre-release, so a < b
        # Both have pre-release identifiers
        ids_a = pre_a.split('.')
        ids_b = pre_b.split('.')
        for i in range(min(len(ids_a), len(ids_b))):
            id_a = ids_a[i]
            id_b = ids_b[i]
            # Check if numeric
            a_is_num = id_a.isdigit()
            b_is_num = id_b.isdigit()
            if a_is_num and b_is_num:
                num_a = int(id_a)
                num_b = int(id_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif a_is_num and not b_is_num:
                # Numeric identifiers always have lower precedence than alphanumeric
                return -1
            elif not a_is_num and b_is_num:
                return 1
            else:
                # Both alphanumeric, compare lexically
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
        # All compared identifiers are equal, longer list has higher precedence
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1
        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major, minor, patch
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare pre-release
    return compare_pre_release(pre_a, pre_b)
