def parse_range(header, size):
    """
    Parse an RFC 7233 Range header for bytes.

    Args:
        header: The Range header value (e.g., "bytes=0-499")
        size: The total size of the resource in bytes

    Returns:
        A list of (start, end) inclusive byte offsets, or None if unsatisfiable/malformed.
    """
    if not header or not isinstance(header, str):
        return None

    # Check for "bytes=" prefix
    if not header.startswith("bytes="):
        return None

    range_spec = header[6:]  # Remove "bytes="

    if not range_spec:
        return None

    # Split by comma
    ranges = [r.strip() for r in range_spec.split(",")]

    if not ranges:
        return None

    results = []

    for r in ranges:
        if not r:
            return None

        # Parse the range
        if "-" not in r:
            return None

        parts = r.split("-", 1)
        start_str = parts[0].strip()
        end_str = parts[1].strip()

        if start_str == "" and end_str == "":
            return None

        # Handle suffix range: bytes=-500
        if start_str == "":
            # Suffix range: last N bytes
            try:
                suffix_len = int(end_str)
            except ValueError:
                return None

            if suffix_len <= 0:
                return None

            # If suffix length is larger than resource, return whole resource
            if suffix_len >= size:
                start = 0
                end = size - 1
            else:
                start = size - suffix_len
                end = size - 1

            results.append((start, end))

        # Handle open-ended range: bytes=500-
        elif end_str == "":
            try:
                start = int(start_str)
            except ValueError:
                return None

            if start >= size:
                # Unsatisfiable
                continue

            end = size - 1
            results.append((start, end))

        # Handle explicit range: bytes=0-499
        else:
            try:
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                return None

            if start > end:
                return None

            if start >= size:
                # Unsatisfiable
                continue

            # Clamp end to size - 1
            if end >= size:
                end = size - 1

            results.append((start, end))

    if not results:
        return None

    return results
