from decimal import Decimal, ROUND_HALF_EVEN

def round_money(amount: Decimal, places: int) -> Decimal:
    if not isinstance(amount, Decimal):
        raise TypeError("amount must be a Decimal")
    if not isinstance(places, int):
        raise TypeError("places must be an integer")

    quantize_str = '1.' + '0' * places if places > 0 else '1'
    if places == 0:
        quantize_str = '1'
    elif places < 0:
        quantize_str = '1' + '0' * (-places)

    return amount.quantize(Decimal(quantize_str), rounding=ROUND_HALF_EVEN)
