class WildcardTrie:
    def __init__(self):
        self.root = {}
        self.words = set()

    def add(self, word):
        self.words.add(word)
        node = self.root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        node['$'] = True

    def remove(self, word):
        if word not in self.words:
            return False
        self.words.remove(word)
        # Remove from trie
        stack = []
        node = self.root
        for ch in word:
            stack.append((node, ch))
            node = node[ch]
        # Check if the leaf node has only the '$' marker
        if '$' in node and len(node) == 1:
            # Remove the '$' marker
            del node['$']
            # Backtrack to remove empty nodes
            for parent, ch in reversed(stack):
                if len(parent[ch]) == 0:
                    del parent[ch]
                else:
                    break
        return True

    def search(self, pattern):
        results = []
        self._search_dfs(self.root, pattern, 0, "", results)
        return sorted(results)

    def _search_dfs(self, node, pattern, idx, current, results):
        if idx == len(pattern):
            if '$' in node:
                results.append(current)
            return
        ch = pattern[idx]
        if ch == '.':
            for key in node:
                if key == '$':
                    continue
                self._search_dfs(node[key], pattern, idx + 1, current + key, results)
        else:
            if ch in node:
                self._search_dfs(node[ch], pattern, idx + 1, current + ch, results)
