import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    # Dijkstra with heap
    # dist[node] = (cost, num_edges, path)
    # We want to minimize cost, then num_edges, then lexicographic path

    # Initialize distances
    dist = {src: (0, 0, [src])}
    heap = [(0, 0, [src])]  # (cost, num_edges, path)

    while heap:
        cost, num_edges, path = heapq.heappop(heap)
        node = path[-1]

        # If we've already found a better path to this node, skip
        if node in dist:
            d_cost, d_edges, d_path = dist[node]
            if (cost, num_edges, path) > (d_cost, d_edges, d_path):
                continue

        # If we reached the destination, return
        if node == dst:
            return (cost, path)

        # Explore neighbors
        if node in graph:
            for neighbor, weight in graph[node]:
                new_cost = cost + weight
                new_edges = num_edges + 1
                new_path = path + [neighbor]

                if neighbor not in dist:
                    dist[neighbor] = (new_cost, new_edges, new_path)
                    heapq.heappush(heap, (new_cost, new_edges, new_path))
                else:
                    d_cost, d_edges, d_path = dist[neighbor]
                    # Compare: first by cost, then by num_edges, then by lexicographic path
                    if (new_cost, new_edges, new_path) < (d_cost, d_edges, d_path):
                        dist[neighbor] = (new_cost, new_edges, new_path)
                        heapq.heappush(heap, (new_cost, new_edges, new_path))

    return (None, [])
