import heapq
from collections import defaultdict

def topo_lex(graph):
    """
    graph: dict mapping node -> list of nodes that depend on it (successors)
    Returns lexicographically smallest topological ordering, or None if cycle exists.
    """
    # Collect all nodes
    all_nodes = set()
    for node, successors in graph.items():
        all_nodes.add(node)
        for succ in successors:
            all_nodes.add(succ)

    if not all_nodes:
        return []

    # Build in-degree count and adjacency list (node -> successors)
    # In-degree: number of predecessors for each node
    in_degree = defaultdict(int)
    adj = defaultdict(list)

    for node in all_nodes:
        in_degree[node] = 0

    for node, successors in graph.items():
        for succ in successors:
            adj[node].append(succ)
            in_degree[succ] += 1

    # Initialize heap with nodes that have in_degree 0
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for succ in adj[node]:
            in_degree[succ] -= 1
            if in_degree[succ] == 0:
                heapq.heappush(heap, succ)

    if len(result) != len(all_nodes):
        return None

    return result
