const jsonPointer = {
  get(doc, pointer) {
    if (pointer === '') {
      return doc;
    }
    if (typeof pointer !== 'string' || pointer[0] !== '/') {
      throw new Error('Invalid JSON Pointer: must be empty or start with "/"');
    }

    const tokens = pointer.substring(1).split('/').map(token => {
      // Decode ~1 to / and ~0 to ~, in that order
      return token.replace(/~1/g, '/').replace(/~0/g, '~');
    });

    let current = doc;
    for (const token of tokens) {
      if (current === null || current === undefined) {
        return undefined;
      }
      if (Array.isArray(current)) {
        // Numeric token indexes an array
        const index = parseInt(token, 10);
        if (isNaN(index) || index < 0 || index >= current.length) {
          return undefined;
        }
        current = current[index];
      } else if (typeof current === 'object') {
        if (!(token in current)) {
          return undefined;
        }
        current = current[token];
      } else {
        return undefined;
      }
    }

    return current;
  },

  set(doc, pointer, value) {
    if (pointer === '') {
      return value;
    }
    if (typeof pointer !== 'string' || pointer[0] !== '/') {
      throw new Error('Invalid JSON Pointer: must be empty or start with "/"');
    }

    const tokens = pointer.substring(1).split('/').map(token => {
      // Decode ~1 to / and ~0 to ~, in that order
      return token.replace(/~1/g, '/').replace(/~0/g, '~');
    });

    let current = doc;
    for (let i = 0; i < tokens.length - 1; i++) {
      const token = tokens[i];
      if (current === null || current === undefined) {
        throw new Error('Cannot set value on null/undefined');
      }
      if (Array.isArray(current)) {
        const index = parseInt(token, 10);
        if (isNaN(index) || index < 0) {
          throw new Error('Invalid array index');
        }
        if (current[index] === undefined) {
          // Create missing intermediate object
          current[index] = {};
        }
        current = current[index];
      } else if (typeof current === 'object') {
        if (!(token in current) || current[token] === undefined || current[token] === null) {
          // Create missing intermediate object
          current[token] = {};
        }
        current = current[token];
      } else {
        throw new Error('Cannot traverse non-object/array');
      }
    }

    const lastToken = tokens[tokens.length - 1];

    if (Array.isArray(current)) {
      if (lastToken === '-') {
        // Append to array
        current.push(value);
      } else {
        const index = parseInt(lastToken, 10);
        if (isNaN(index) || index < 0) {
          throw new Error('Invalid array index');
        }
        current[index] = value;
      }
    } else if (typeof current === 'object' && current !== null) {
      current[lastToken] = value;
    } else {
      throw new Error('Cannot set value on non-object/array');
    }

    return doc;
  }
