function zipLongest(fill, ...iterables) {
  const iterators = iterables.map(it => it[Symbol.iterator]());
  const done = new Array(iterators.length).fill(false);

  return {
    [Symbol.iterator]() {
      return this;
    },
    next() {
      const row = [];
      let anyActive = false;

      for (let i = 0; i < iterators.length; i++) {
        if (done[i]) {
          row.push(fill);
        } else {
          const result = iterators[i].next();
          if (result.done) {
            done[i] = true;
            row.push(fill);
          } else {
            row.push(result.value);
            anyActive = true;
          }
        }
      }

      if (!anyActive && iterators.length > 0) {
        // All iterators are done
        return { done: true, value: undefined };
      }

      if (iterators.length === 0) {
        return { done: true, value: undefined };
      }

      return { done: false, value: row };
    }
  };
}

module.exports = zipLongest;
