export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends object
    ? T extends Function
      ? T
      : T extends Array<infer U>
        ? Array<DeepAwaited<U>>
        : { [K in keyof T]: DeepAwaited<T[K]> }
    : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value instanceof Promise) {
    const resolved = await value;
    return deepAwait(resolved) as DeepAwaited<T>;
  }

  if (value === null || value === undefined || typeof value !== 'object') {
    return value as DeepAwaited<T>;
  }

  if (typeof value === 'function') {
    return value as DeepAwaited<T>;
  }

  if (Array.isArray(value)) {
    const result = await Promise.all(
      value.map((item) => deepAwait(item))
    );
    return result as DeepAwaited<T>;
  }

  const keys = Object.keys(value) as Array<keyof T>;
  const result: Record<string, unknown> = {};
  for (const key of keys) {
    result[key as string] = await deepAwait((value as Record<string, unknown>)[key as string]);
  }
  return result as DeepAwaited<T>;
}
