type KeysOf<T> = keyof T;

type PickKeys<T, K extends KeysOf<T>> = K;

type OmitKeys<T, K extends KeysOf<T>> = Exclude<KeysOf<T>, K>;

type PickResult<T, K extends KeysOf<T>> = {
  [P in K as P extends KeysOf<T> ? P : never]: T[P];
};

type OmitResult<T, K extends KeysOf<T>> = {
  [P in OmitKeys<T, K>]: T[P];
};

export function pick<T extends object, K extends KeysOf<T>>(
  obj: T,
  keys: readonly K[]
): PickResult<T, K> {
  const result = {} as PickResult<T, K>;
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      (result as any)[key] = (obj as any)[key];
    }
  }
  return result;
}

export function omit<T extends object, K extends KeysOf<T>>(
  obj: T,
  keys: readonly K[]
): OmitResult<T, K> {
  const keysSet = new Set<string | number | symbol>(keys);
  const result = {} as OmitResult<T, K>;
  for (const key of Object.keys(obj) as (keyof T)[]) {
    if (!keysSet.has(key)) {
      (result as any)[key] = (obj as any)[key];
    }
  }
  return result;
}
