export type DeepPartial<T> = T extends Array<any>
  ? T
  : T extends (...args: any[]) => any
    ? T
    : T extends object
      ? { [K in keyof T]?: DeepPartial<T[K]> }
      : T;

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined || patch === null) {
    return base;
  }

  if (Array.isArray(base) || Array.isArray(patch)) {
    // Arrays are replaced wholesale if patch is an array, otherwise keep base
    if (Array.isArray(patch)) {
      return patch as unknown as T;
    }
    return base;
  }

  if (typeof base !== 'object' || base === null) {
    return base;
  }

  if (typeof patch !== 'object' || patch === null) {
    return base;
  }

  const result: Record<string, any> = { ...base as Record<string, any> };

  for (const key of Object.keys(patch)) {
    const patchValue = (patch as Record<string, any>)[key];
    // Treat explicit undefined as 'leave alone'
    if (patchValue === undefined) {
      continue;
    }

    const baseValue = (base as Record<string, any>)[key];
    result[key] = applyPatch(baseValue, patchValue);
  }

  return result as T;
}
